roomClearFunction:
static int GetRoomClearFlagForActor(PlayState *play, int flag)
{
    int res;

    res = Flags_GetClear(play, flag);
    if (Config_Flag(CFG_ER_WALLMASTERS) && sActorIdToSpawn == ACTOR_EN_WALLMAS)
        res = 0;
    return res;
}

transportFunction:
void EnWallmas_TakePlayerEr(PlayState* play, Actor* this)
{
    comboClearCustomRespawn(CUSTOM_RESPAWN_MODE_DUNGEON_ENTRANCE);
    play->nextEntranceIndex = EnWallmas_GetDestEr(this, play);
    play->transitionTrigger = TRANS_TRIGGER_START;
    play->transitionType = TRANS_GFX_BLACK;
    gIsEntranceOverride = 1;
}
